from typing import List

def generate_prime_factors(n: int) -> List[int]:
    factors = []
    divisor = 2
    while n > 1:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1
    return factors

def count_occurrences(factors: List[int]) -> List[int]:
    occurrences = []
    current_factor = None
    count = 0
    for factor in factors:
        if factor == current_factor:
            count += 1
        else:
            if current_factor is not None:
                occurrences.extend([current_factor] * count)
            current_factor = factor
            count = 1
    if current_factor is not None:
        occurrences.extend([current_factor] * count)
    return occurrences

def factorize(n: int) -> List[int]:
    if n == 1:
        return []
    prime_factors = generate_prime_factors(n)
    return count_occurrences(prime_factors)

